# Generated from tools/data/rulebooks/uno.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Uno
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:hand, GameRoomRules.translate("Match a card and try to empty your hand"),
            GameRoomRules.translate("UNO is for two to eight players. Each round starts with seven cards per person. On your turn, play a card matching the current colour or the number or symbol on the top discard. On a blue seven, for example, you may play a blue card or a seven of another colour. Wild cards let you choose the next colour."),
            GameRoomRules.translate("Usually you play one card and the turn moves on. The first empty hand wins the round, although a final drawing penalty or buzzer must be resolved before points are counted. With one card left, announce UNO. Another player can catch the missing announcement in the response window, making its owner draw two cards."),
            GameRoomRules.translate("You want as few points as possible. The round winner receives zero; everyone else adds the value of cards still held. Number cards count their number, coloured action cards 20 and wild cards 50. The elimination limit is normally 500, configurable from 50 to 5000. Players reaching it leave after the round, while the others continue. The last remaining player wins the whole game.")),
          rule_section(:draw, GameRoomRules.translate("Drawing is not always the end of your turn"),
            GameRoomRules.translate("An ordinary draw takes one card. If you still have no legal card afterwards, your turn ends automatically. Otherwise you may play. When the pile runs out, discards except the top card are shuffled back for drawing; nobody loses their hand."),
            GameRoomRules.translate("Allow drawing with a playable card is on by default. Its separate limit is normally three voluntary cards per turn, from one to twenty. At the limit, another press only reports that you cannot draw; it does not secretly end the turn. If optional drawing is off, having a legal card prevents an ordinary draw."),
            GameRoomRules.translate("Draw until a playable card is off by default. If enabled, one draw action keeps taking cards until a playable card is found or the available supply ends. Penalty draws are separate: they take the amount currently owed, not this ordinary-drawing allowance."),
            GameRoomRules.translate("Skip the turn after drawing a penalty is off by default. With it on, paying a penalty always ends your turn. With it off, you may still play if your resulting hand has a legal card; otherwise the turn ends automatically. You do not have to draw again just to confirm that you cannot play.")),
          rule_section(:classic, GameRoomRules.translate("The classic deck and drawing attacks"),
            GameRoomRules.translate("Classic is the default deck: four colours, numbers from zero to nine, Skip, Reverse, Draw Two, Wild and Wild Draw Four. Skip misses the next player; Reverse changes direction and normally acts as Skip with two players. Draw Two adds two cards to a penalty, while Wild Draw Four adds four and changes colour."),
            GameRoomRules.translate("A colour-changing wild is played in two steps. First it leaves your hand and becomes the table card; then you select a colour. Nobody can intercept between those steps. A configured thinking timer is paused during this colour choice. The next player receives their full turn time once the colour is chosen."),
            GameRoomRules.translate("Draw responses, on by default, lets you pass a drawing debt on by adding another permitted drawing card. In Classic it must be the same kind: Draw Two answers Draw Two, Wild Draw Four answers Wild Draw Four. The next player owes the accumulated amount. Without this option, you must take the debt instead."),
            GameRoomRules.translate("Advanced responses requires ordinary responses and is off by default. Skip or Wild passes the debt onwards; Reverse sends it in the other direction. In No Mercy, Discard All and Skip Everyone instead cancel a pending numerical drawing penalty."),
            GameRoomRules.translate("Challenging Wild Draw Four is an optional Classic-only rule. If its author still had a card of the previous colour, a successful challenge makes them draw four instead. If the play was justified, the challenger draws six and loses the turn. The option is off by default; the game does not automatically challenge every wild.")),
          rule_section(:decks, GameRoomRules.translate("No Mercy and Flip"),
            GameRoomRules.translate("No Mercy adds coloured Draw Four and wild Draw Six, Draw Ten and Reverse Draw Four. Drawing responses stay in their family, coloured or wild, and cannot be weaker than the last attack. Reverse Draw Four also reverses direction; with two players its debt returns to the player who used it."),
            GameRoomRules.translate("No Mercy also has Skip Everyone, which gives another play; Discard All, which removes your other cards of the played colour; and Colour Roulette. Roulette makes the next player draw until a non-wild card of the chosen colour appears, then ends their turn."),
            GameRoomRules.translate("The No Mercy card limit normally removes a player from the round at 25 cards and adds 250 points. You can choose a limit from 10 to 100, or zero to disable it. This is not necessarily elimination from the whole game: the player returns next round unless their total score has reached the overall elimination limit."),
            GameRoomRules.translate("Flip uses two-sided cards. Playing Flip turns every hand and both piles over and reverses the pile order. The light side has Draw One and Wild Draw Two; the dark side has its own colours, Draw Five, Skip Everyone and wild colour drawing. Only the active side determines matching and effects. Power Games counts coloured action cards as 20 and wild cards as 50 on either side.")),
          rule_section(:speed, GameRoomRules.translate("Optional fast reactions and hand exchanges"),
            GameRoomRules.translate("Interceptions lets you play out of turn with a non-wild card identical in colour and face to the top discard. You take over play, subject to that card's effect; intercepting with a drawing attack does not make you pay your own attack. Super interceptions relaxes the colour requirement but still requires the same face. Both options are off by default, and Super requires ordinary interceptions."),
            GameRoomRules.translate("With interceptions enabled, trying a nonmatching card during someone else's turn says Too late and adds three penalty points. The card stays in your hand. This also applies during a bot's pause, without a special exemption for mistaken key presses. It does not apply to ordinary wrong moves on your own turn or to buzzer response windows. Score-limit elimination is checked at the round's end."),
            GameRoomRules.translate("Straights, off by default, lets you follow your own number-card play with consecutive numbers of the same colour, going up or down. For example, red eight, seven, six. Each card is a separate play. You can continue only until another player plays or intercepts; there is no separate timed straight window, and you cannot start the sequence out of turn."),
            GameRoomRules.translate("Zero and seven hand swapping is off by default. A seven exchanges your hand with a chosen opponent; a zero passes all active hands in the direction of play. Buzzer cards, also off, adds eight universal buzzer cards to Classic or No Mercy, not Flip. After a buzzer, everyone still active responds with B and the last responder draws two. Any card may follow a buzzer."),
            GameRoomRules.translate("Thinking time is unlimited at zero, or can be set from one to 300 seconds. Expiry takes the pending drawing penalty, or one penalty card if there is no pending penalty, then ends the turn. This penalty also applies when you have already drawn voluntarily. Buzzer responses and colour selection pause the timer. The game does not interrupt play with automatic time-remaining announcements.")),
          rule_section(:controls, GameRoomRules.translate("Game keyboard shortcuts"),
            GameRoomRules.translate("Arrows: browse cards or colour choices."),
            GameRoomRules.translate("Enter: play the card, or confirm the requested colour or player."),
            GameRoomRules.translate("Space: draw a card or accept the pending draw penalty."),
            GameRoomRules.translate("U: say UNO or catch a missing UNO."),
            GameRoomRules.translate("B: respond to the buzzer."),
            GameRoomRules.translate("F: challenge Wild Draw Four."),
            GameRoomRules.translate("C: read the top card."),
            GameRoomRules.translate("V: read the current colour."),
            GameRoomRules.translate("E: read each player's card count."),
            GameRoomRules.translate("G: read the pending penalty."),
            GameRoomRules.translate("Z: next legal card on your turn; disabled with straights, interceptions or buzzer cards."),
            GameRoomRules.translate("Shift+Z: previous legal card on your turn; disabled with straights, interceptions or buzzer cards."),
            GameRoomRules.translate("Shift+D: restore acquisition order."),
            GameRoomRules.translate("S: read scores."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("Shift+C: sort by suit or colour; press again to reverse the order."),
            GameRoomRules.translate("Shift+H: sort by rank or value; press again to reverse the order."),
            GameRoomRules.translate("Shift+M: restore the order in which cards were received."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry",
              "V UNO chce\u0161 jako prvn\u00ED vylo\u017Eit v\u0161echny sv\u00E9 karty. Zbytek v ruce na konci kola p\u0159in\u00E1\u0161\u00ED trestn\u00E9 body. Dosa\u017Een\u00ED bodov\u00E9ho limitu t\u011B vy\u0159ad\u00ED; posledn\u00ED zb\u00FDvaj\u00EDc\u00ED hr\u00E1\u010D vyhraje celou partii.",
              "Hraj\u00ED dva a\u017E osm hr\u00E1\u010D\u016F, ka\u017Ed\u00FD dostane sedm karet. Za\u010D\u00EDn\u00E1 hr\u00E1\u010D po rozd\u00E1vaj\u00EDc\u00EDm."),
            rule_section(:turn, "B\u011B\u017En\u00FD tah",
              "Pomoc\u00ED C si p\u0159e\u010Dti vrchn\u00ED kartu na stole. Tvoje karta mus\u00ED odpov\u00EDdat barvou, \u010D\u00EDslem nebo symbolem. Na modrou \u0161estku tedy pasuje modr\u00E1 karta nebo \u0161estka jin\u00E9 barvy. Vyber \u0161ipkami a zahraj Enterem.",
              "Po b\u011B\u017En\u00E9 kart\u011B hraje dal\u0161\u00ED. Nem\u00E1\u0161-li vhodnou, dober mezern\u00EDkem. Potom sm\u00ED\u0161 zahr\u00E1t kteroukoli p\u0159\u00EDpustnou kartu v ruce, i d\u0159\u00EDve dr\u017Eenou. Pokud po dobr\u00E1n\u00ED st\u00E1le nem\u00E1\u0161 jedin\u00FD tah, kon\u010D\u00ED\u0161 automaticky.",
              "Dob\u00EDrat sm\u00ED\u0161 i m\u00EDsto zahr\u00E1n\u00ED vhodn\u00E9 karty, nejv\u00FD\u0161 v\u0161ak t\u0159ikr\u00E1t b\u011Bhem tahu. Po t\u0159et\u00EDm dobr\u00E1n\u00ED u\u017E mus\u00ED\u0161 zahr\u00E1t, m\u00E1\u0161-li \u010D\u00EDm.",
              "Po vy\u010Derp\u00E1n\u00ED dob\u00EDrac\u00EDho bal\u00ED\u010Dku se d\u0159\u00EDve zahran\u00E9 karty zam\u00EDchaj\u00ED a znovu pou\u017Eij\u00ED."),
            rule_section(:special, "Zvl\u00E1\u0161tn\u00ED karty",
              "Vedle \u010D\u00EDseln\u00FDch karet se pou\u017E\u00EDvaj\u00ED tyto \u00FA\u010Dinky:",
              "- P\u0159esko\u010Den\u00ED vezme n\u00E1sleduj\u00EDc\u00EDmu hr\u00E1\u010Di tah.",
              "- Zm\u011Bna sm\u011Bru obr\u00E1t\u00ED po\u0159ad\u00ED hry. Ve dvou funguje jako p\u0159esko\u010Den\u00ED, tak\u017Ee hraje\u0161 znovu.",
              "- Karta \u201EZm\u011Bna barvy\u201C, tedy divok\u00E1 karta, dovol\u00ED zvolit novou barvu bez p\u0159izp\u016Fsoben\u00ED p\u0159edchoz\u00ED kart\u011B. Po zahr\u00E1n\u00ED barvu vyber \u0161ipkami a potvr\u010F Enterem. Platnou barvu p\u0159ipomene V.",
              "- Karta \u201EDobrat dv\u011B\u201C, zkr\u00E1cen\u011B plus dva, ukl\u00E1d\u00E1 dal\u0161\u00EDmu hr\u00E1\u010Di dobrat dv\u011B karty. M\u016F\u017Ee odpov\u011Bd\u011Bt vlastn\u00EDm plus dva, zv\u00FD\u0161it trest na \u010Dty\u0159i a poslat ho d\u00E1l. Dal\u0161\u00ED odpov\u011Bdi trest d\u00E1l s\u010D\u00EDtaj\u00ED.",
              "- Karta \u201EZm\u011Bna barvy a dobrat \u010Dty\u0159i\u201C, zkr\u00E1cen\u011B divok\u00E1 plus \u010Dty\u0159i, m\u011Bn\u00ED barvu a ukl\u00E1d\u00E1 \u010Dty\u0159i karty. Odpov\u011Bd\u011Bt lze dal\u0161\u00ED divokou plus \u010Dty\u0159i. Tresty plus dva a plus \u010Dty\u0159i se mezi sebou nem\u00EDchaj\u00ED.",
              "Trest p\u0159ijme\u0161 mezern\u00EDkem a vezme\u0161 cel\u00FD po\u010Det karet; jeho v\u00FD\u0161i p\u0159e\u010Dte G. Pak je\u0161t\u011B sm\u00ED\u0161 zahr\u00E1t vhodnou kartu. Nem\u00E1\u0161-li \u017E\u00E1dnou, tah skon\u010D\u00ED."),
            rule_section(:ending, "Uno a konec kola",
              "S jedinou kartou stiskni U a ohlas \u201Euno\u201C. Zapomene-li n\u011Bkdo, soupe\u0159 ho chyt\u00ED stejnou kl\u00E1vesou, dokud nenastane dal\u0161\u00ED zahr\u00E1n\u00ED nebo dobr\u00E1n\u00ED. P\u0159isti\u017Een\u00FD dostane dv\u011B karty.",
              "Posledn\u00ED vylo\u017Een\u00E1 karta vyhraje kolo. Je-li trestn\u00E1, nejd\u0159\u00EDv se vy\u0159e\u0161\u00ED dob\u00EDr\u00E1n\u00ED. V\u00EDt\u011Bz m\u00E1 nula bod\u016F, ostatn\u00ED zap\u00ED\u0161\u00ED zbyl\u00E9 karty:",
              "- \u010C\u00EDseln\u00E1 karta d\u00E1v\u00E1 tolik trestn\u00FDch bod\u016F, kolik je na n\u00ED uvedeno.",
              "- Barevn\u00E1 zvl\u00E1\u0161tn\u00ED karta d\u00E1v\u00E1 20.",
              "- Divok\u00E1 karta d\u00E1v\u00E1 50.",
              "Po kole vypadnou hr\u00E1\u010Di s alespo\u0148 500 body. Ostatn\u00ED dostanou nov\u00E9 karty. Posledn\u00ED hr\u00E1\u010D ve h\u0159e vyhraje celou partii. Sk\u00F3re p\u0159e\u010Dte S."),
            rule_section(:drawing_options, "\u00DApravy dob\u00EDr\u00E1n\u00ED a trest\u016F",
              "N\u00E1sleduj\u00EDc\u00ED varianty se vol\u00ED p\u0159ed hrou v nastaven\u00ED stolu. Dob\u00EDr\u00E1n\u00ED a bodov\u00E1n\u00ED lze upravit takto:",
              "- Zm\u011Bnit limit trestn\u00FDch bod\u016F z 500. Vy\u0159azen\u00ED po jeho dosa\u017Een\u00ED se st\u00E1le vyhodnocuje na konci kola.",
              "- Zak\u00E1zat dobrovoln\u00E9 dob\u00EDr\u00E1n\u00ED s vhodnou kartou nebo zm\u011Bnit nejvy\u0161\u0161\u00ED po\u010Det b\u011B\u017En\u00FDch dobr\u00E1n\u00ED za tah.",
              "- Dob\u00EDrat do hrateln\u00E9 karty: jednou stiskne\u0161 mezern\u00EDk a bere\u0161, dokud lze hr\u00E1t nebo dojdou dostupn\u00E9 karty. V\u00FD\u0161e trest\u016F se t\u00EDm nem\u011Bn\u00ED.",
              "- Zak\u00E1zat odpov\u011Bdi na trestn\u00E9 karty. Napaden\u00FD pak mus\u00ED dobrat, nem\u016F\u017Ee poslat trest d\u00E1l.",
              "- Nechat p\u0159ijet\u00ED trestu v\u017Edy ukon\u010Dit tah.",
              "- Pokro\u010Dil\u00E9 odpov\u011Bdi dovol\u00ED p\u0159esko\u010Den\u00EDm nebo b\u011B\u017Enou divokou kartou poslat trest d\u00E1l bez zv\u00FD\u0161en\u00ED. Zm\u011Bna sm\u011Bru ho vr\u00E1t\u00ED opa\u010Dn\u00FDm sm\u011Brem. Tento dopln\u011Bk vy\u017Eaduje povolen\u00E9 odpov\u011Bdi na tresty."),
            rule_section(:challenge, "Zpochybn\u011Bn\u00ED divok\u00E9 plus \u010Dty\u0159i",
              "U klasick\u00E9ho bal\u00ED\u010Dku lze zapnout kontrolu blufov\u00E1n\u00ED. Divokou plus \u010Dty\u0159i pak sm\u00ED\u0161 bez postihu zahr\u00E1t jen tehdy, kdy\u017E nem\u00E1\u0161 jinou kartu dosavadn\u00ED barvy.",
              "Po takov\u00E9m \u00FAtoku m\u016F\u017Ee\u0161 pomoc\u00ED F zkontrolovat soupe\u0159ovu ruku. Pokud odpov\u00EDdaj\u00EDc\u00ED barvu m\u011Bl, dobere \u010Dty\u0159i on. Pokud ji nem\u011Bl, vezme\u0161 \u0161est ty a ztrat\u00ED\u0161 tah."),
            rule_section(:decks, "Volba bal\u00ED\u010Dku",
              "P\u0159ed hrou lze vybrat t\u0159i bal\u00ED\u010Dky:",
              "- Klasick\u00FD odpov\u00EDd\u00E1 z\u00E1kladn\u00EDm pravidl\u016Fm v\u00FD\u0161e.",
              "- No Mercy p\u0159id\u00E1v\u00E1 siln\u011Bj\u0161\u00ED \u00FAtoky a vy\u0159azen\u00ED z kola za p\u0159\u00EDli\u0161 velkou ruku.",
              "- Flip m\u00E1 oboustrann\u00E9 karty; zahr\u00E1n\u00ED Flipu zm\u011Bn\u00ED pou\u017E\u00EDvanou stranu. Podrobnosti n\u00E1sleduj\u00ED za No Mercy."),
            rule_section(:no_mercy, "No Mercy",
              "No Mercy zachov\u00E1v\u00E1 p\u0159ikl\u00E1d\u00E1n\u00ED i bodov\u00E1n\u00ED klasick\u00E9ho UNO a p\u0159id\u00E1v\u00E1 dal\u0161\u00ED karty:",
              "- Barevn\u00E1 karta \u201EDobrat \u010Dty\u0159i\u201C, tedy plus \u010Dty\u0159i, ukl\u00E1d\u00E1 n\u00E1sleduj\u00EDc\u00EDmu hr\u00E1\u010Di \u010Dty\u0159i karty.",
              "- \u201EZm\u011Bna barvy a dobrat \u0161est\u201C a \u201EZm\u011Bna barvy a dobr\u00E1n\u00ED deseti karet\u201C jsou divok\u00E9 plus \u0161est a plus deset: dovoluj\u00ED zm\u011Bnit barvu a ukl\u00E1daj\u00ED p\u0159\u00EDslu\u0161n\u00FD po\u010Det karet.",
              "- \u201EDivok\u00E1 karta: zm\u011Bna sm\u011Bru a dobr\u00E1n\u00ED \u010Dty\u0159\u201C obr\u00E1t\u00ED hru a napadne nov\u011B n\u00E1sleduj\u00EDc\u00EDho hr\u00E1\u010De. Ve dvou se trest vr\u00E1t\u00ED na toho, kdo ji zahr\u00E1l.",
              "- Karta \u201EVynechat v\u0161echny\u201C ti d\u00E1v\u00E1 okam\u017Eit\u011B dal\u0161\u00ED tah.",
              "- Karta \u201EOdhodit v\u0161echny\u201C odstran\u00ED z ruky i ostatn\u00ED karty stejn\u00E9 barvy.",
              "- Divok\u00E1 barevn\u00E1 ruleta nut\u00ED dal\u0161\u00EDho hr\u00E1\u010De dob\u00EDrat a\u017E po prvn\u00ED nedivokou kartu barvy, kterou ur\u010D\u00ED\u0161. Potom jeho tah kon\u010D\u00ED.",
              "Proti trestu s ur\u010Dit\u00FDm po\u010Dtem mus\u00ED obrana pat\u0159it do stejn\u00E9 skupiny: barevn\u00E1 proti barevn\u00E9, divok\u00E1 proti divok\u00E9. Z\u00E1rove\u0148 nesm\u00ED b\u00FDt slab\u0161\u00ED ne\u017E posledn\u00ED \u00FAtok. Na barevnou plus \u010Dty\u0159i tedy nelze d\u00E1t plus dva.",
              "S pokro\u010Dil\u00FDmi odpov\u011B\u010Fmi lze kartou \u201EVynechat v\u0161echny\u201C nebo \u201EOdhodit v\u0161echny\u201C \u00FApln\u011B zru\u0161it trest za ur\u010Dit\u00FD po\u010Det karet.",
              "Jakmile m\u00E1\u0161 v ruce 25 karet, vypadne\u0161 z aktu\u00E1ln\u00EDho kola a dostane\u0161 250 trestn\u00FDch bod\u016F. V dal\u0161\u00EDm kole se vr\u00E1t\u00ED\u0161, pokud u\u017E body nezp\u016Fsobily celkov\u00E9 vy\u0159azen\u00ED. Hranici 25 lze zm\u011Bnit nebo nulou vypnout."),
            rule_section(:flip, "Flip",
              "Flip m\u00E1 sv\u011Btlou a tmavou stranu karet. Za\u010D\u00EDn\u00E1 se sv\u011Btlou. Karta Flip, v seznamu nazvan\u00E1 \u201EOto\u010Dit karty\u201C, obr\u00E1t\u00ED v\u0161echny ruce i oba bal\u00ED\u010Dky, tak\u017Ee jejich dosavadn\u00ED spodn\u00ED karty budou naho\u0159e. Od t\u00E9 chv\u00EDle se hraje podle nov\u011B odhalen\u00E9 strany.",
              "Strany maj\u00ED odli\u0161n\u00E9 zvl\u00E1\u0161tn\u00ED karty:",
              "- Sv\u011Btl\u00E1 obsahuje mimo jin\u00E9 barevn\u00E9 plus jedna (\u201EDoberte jednu\u201C) a divok\u00E9 plus dva (\u201EZm\u011Bna barvy a dobr\u00E1n\u00ED dvou karet\u201C).",
              "- Tmav\u00E1 p\u0159in\u00E1\u0161\u00ED jin\u00E9 barvy a barevn\u00E9 plus p\u011Bt (\u201EDobrat p\u011Bt\u201C). Karta \u201EVynechat v\u0161echny\u201C d\u00E1v\u00E1 dal\u0161\u00ED tah tomu, kdo ji zahr\u00E1l.",
              "- Tmav\u00E1 \u201EDivok\u00E1 karta s dob\u00EDr\u00E1n\u00EDm do zvolen\u00E9 barvy\u201C nut\u00ED dal\u0161\u00EDho hr\u00E1\u010De br\u00E1t a\u017E po prvn\u00ED nedivokou kartu po\u017Eadovan\u00E9 barvy. T\u00EDm jeho tah kon\u010D\u00ED.",
              "Bodov\u00E1n\u00ED zvl\u00E1\u0161tn\u00EDch karet se nem\u011Bn\u00ED: barevn\u00E9 jsou za 20, divok\u00E9 za 50."),
            rule_section(:extra_rules, "P\u0159eb\u00EDr\u00E1n\u00ED tahu a dal\u0161\u00ED dodatky",
              "P\u0159ed hrou lze zapnout tak\u00E9 tyto mo\u017Enosti:",
              "- P\u0159eb\u00EDr\u00E1n\u00ED tahu dovol\u00ED mimo vlastn\u00ED po\u0159ad\u00ED zahr\u00E1t toto\u017Enou nedivokou kartu s vrchn\u00ED kartou na stole. Vyber ji a stiskni Enter. P\u0159evezme\u0161 tah a \u00FA\u010Dinek m\u00ED\u0159\u00ED na n\u00E1sleduj\u00EDc\u00EDho hr\u00E1\u010De. Neplatn\u00FD pokus stoj\u00ED t\u0159i trestn\u00E9 body. P\u0159i zapnut\u00E9m superp\u0159eb\u00EDr\u00E1n\u00ED tahu podle hodnoty sta\u010D\u00ED shodn\u00E9 \u010D\u00EDslo \u010Di symbol bez shodn\u00E9 barvy. Tato volba vy\u017Eaduje zapnut\u00E9 b\u011B\u017En\u00E9 p\u0159eb\u00EDr\u00E1n\u00ED tahu.",
              "- Postupky dovol\u00ED po vlastn\u00EDm zahr\u00E1n\u00ED rychle p\u0159id\u00E1vat sousedn\u00ED \u010D\u00EDsla stejn\u00E9 barvy jedn\u00EDm sm\u011Brem. Po zelen\u00E9 p\u011Btce tak m\u016F\u017Ee\u0161 p\u0159idat \u0161estku a sedmi\u010Dku. Ka\u017Edou vyber a zahraj Enterem zvl\u00E1\u0161\u0165, dodr\u017E rostouc\u00ED \u010Di klesaj\u00EDc\u00ED sm\u011Br a stihni to p\u0159ed ciz\u00EDm zahr\u00E1n\u00EDm.",
              "- V\u00FDm\u011Bny rukou: sedmi\u010Dka dovol\u00ED vybrat soupe\u0159e \u0161ipkami a Enterem a vym\u011Bnit si cel\u00E9 ruce. Nula p\u0159ed\u00E1 ka\u017Edou ruku n\u00E1sleduj\u00EDc\u00EDmu hr\u00E1\u010Di ve sm\u011Bru hry. Byla-li nula nebo sedmi\u010Dka tvou posledn\u00ED kartou, p\u0159ed\u00E1\u0161 pr\u00E1zdnou ruku jin\u00E9mu hr\u00E1\u010Di a kolo vyhraje on.",
              "- Bzu\u010D\u00E1ky p\u0159idaj\u00ED osm karet do klasick\u00E9ho bal\u00ED\u010Dku \u010Di No Mercy. Po bzu\u010D\u00E1ku v\u0161ichni stisknou B, posledn\u00ED si vezme dv\u011B karty. Pak lze zahr\u00E1t cokoli. Byl-li bzu\u010D\u00E1k posledn\u00ED kartou, kolo skon\u010D\u00ED a\u017E po reakc\u00EDch v\u0161ech. Ve Flipu bzu\u010D\u00E1ky nejsou.",
              "- \u010Cas na tah: kdo ho p\u0159ekro\u010D\u00ED, p\u0159ijme \u010Dekaj\u00EDc\u00ED trest, nebo bez trestu jednu kartu, a ztrat\u00ED tah. Volba barvy a reakce na bzu\u010D\u00E1k odpo\u010Det zastav\u00ED."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipky: proch\u00E1zet karty \u010Di barvy.",
              "Enter: zahr\u00E1t kartu nebo potvrdit barvu \u010Di hr\u00E1\u010De.",
              "Mezern\u00EDk: dobrat nebo p\u0159ijmout trest.",
              "U: ohl\u00E1sit uno nebo chytit hr\u00E1\u010De, kter\u00FD ho neohl\u00E1sil.",
              "B: reagovat na bzu\u010D\u00E1k.",
              "F: zpochybnit divokou plus \u010Dty\u0159i.",
              "C: p\u0159e\u010D\u00EDst vrchn\u00ED kartu.",
              "V: p\u0159e\u010D\u00EDst platnou barvu.",
              "E: p\u0159e\u010D\u00EDst po\u010Dty karet hr\u00E1\u010D\u016F.",
              "G: p\u0159e\u010D\u00EDst \u010Dekaj\u00EDc\u00ED trest.",
              "Z: naj\u00EDt dal\u0161\u00ED p\u0159\u00EDpustnou kartu ve vlastn\u00EDm tahu; nedostupn\u00E9 s postupkami, p\u0159eb\u00EDr\u00E1n\u00EDm tahu \u010Di bzu\u010D\u00E1ky.",
              "Shift+Z: naj\u00EDt p\u0159edchoz\u00ED p\u0159\u00EDpustnou kartu ve vlastn\u00EDm tahu; nedostupn\u00E9 s postupkami, p\u0159eb\u00EDr\u00E1n\u00EDm tahu \u010Di bzu\u010D\u00E1ky.",
              "S: p\u0159e\u010D\u00EDst sk\u00F3re.",
              "T: ozn\u00E1mit, kdo je na tahu.",
              "Shift+C: se\u0159adit podle barev; opakov\u00E1n\u00EDm obr\u00E1tit po\u0159ad\u00ED.",
              "Shift+H: se\u0159adit podle hodnot; opakov\u00E1n\u00EDm obr\u00E1tit po\u0159ad\u00ED.",
              "Shift+D: obnovit po\u0159ad\u00ED p\u0159ijat\u00FDch karet.",
              "Shift+M: obnovit po\u0159ad\u00ED p\u0159ijat\u00FDch karet.")
          ]
        when "en"
          [
            rule_section(:aim, "Aim of the game",
              "Be the first to play all your cards. Cards left in your hand at the end of a round become penalty points. Reaching the score limit eliminates you from the game; the last player remaining wins.",
              "Two to eight people can play. Everyone starts with seven cards, and the player after the dealer takes the first turn."),
            rule_section(:turn, "Your turn",
              "Press C to hear the last card played. Your card must match its colour, number or symbol. On a blue six, for example, you can play any blue card or a six of another colour. Browse your hand with the arrows and press Enter to play.",
              "After an ordinary play, the turn moves on. If you cannot play, draw with Space. You may then play any suitable card in your hand, not just the one you drew. If you still have no legal play, your turn ends automatically.",
              "You may choose to draw even when you could play, up to three times in one turn. After the third draw, you must play if you can.",
              "When the draw pile runs out, previously played cards are shuffled and become available to draw again."),
            rule_section(:special, "Special cards",
              "Alongside the number cards, you will find:",
              "- Skip: the next player misses a turn.",
              "- Reverse: play changes direction. With two players, it works like Skip, giving you another turn.",
              "- Wild: choose a new colour with the arrows and Enter. A wild does not have to match the previous colour. Press V to hear the chosen colour.",
              "- Draw Two: the next player must draw two cards or respond with another Draw Two. A response passes a four-card penalty to the following player. Each further Draw Two adds another two.",
              "- Wild Draw Four: choose a colour and give the next player a four-card penalty. They can respond with another Wild Draw Four. Draw Two and Wild Draw Four cannot be stacked together.",
              "Press Space to take a draw penalty. You receive all the required cards; G tells you how many are pending. After drawing, you can still play a suitable card. If you have none, your turn ends."),
            rule_section(:ending, "Calling uno and scoring",
              "When you have one card left, press U to call uno. If another player forgets, press U to catch them before the next card is played or drawn. A player caught this way receives two extra cards.",
              "Playing your last card wins the round. If it carries a draw penalty, that penalty is settled first. The winner scores no penalty points; everyone else counts their remaining cards:",
              "- Number cards are worth their printed value.",
              "- Coloured special cards are worth 20 points.",
              "- Wild cards are worth 50 points.",
              "After each round, players with at least 500 points are eliminated. The others receive new hands and play on until only one player remains. Press S for the scores."),
            rule_section(:drawing_options, "Drawing and penalty options",
              "The following sections describe optional table settings. You can change drawing and scoring in these ways:",
              "- Set a score limit other than 500. Players are still eliminated after the round in which they reach it.",
              "- Forbid drawing when a playable card is available, or change the maximum number of ordinary draws per turn.",
              "- Draw until playable: one press of Space keeps drawing until you receive a playable card or the cards run out. It does not change the size of draw penalties.",
              "- Disable penalty responses, so an attacked player must draw instead of passing the penalty on.",
              "- Make accepting a draw penalty always end the player's turn.",
              "- Enable advanced responses: a Skip or ordinary Wild passes the penalty on without increasing it, while Reverse sends it back the other way. Penalty responses must also be enabled."),
            rule_section(:challenge, "Challenging Wild Draw Four",
              "In classic UNO, you can enable challenges. With this rule, playing Wild Draw Four is safe only when you have no other card in the colour that was in play.",
              "If someone attacks you with it, press F to challenge their hand. If they did have that colour, they draw four instead. If they did not, you draw six and lose your turn."),
            rule_section(:decks, "Choosing a deck",
              "The table settings offer three decks:",
              "- Classic uses the cards described in the opening sections.",
              "- No Mercy adds stronger attacks and a hand-size limit that can knock players out of a round.",
              "- Flip gives every card two different sides. Playing a Flip card changes which side everyone uses.",
              "The next two sections explain No Mercy and Flip."),
            rule_section(:no_mercy, "No Mercy",
              "No Mercy keeps classic UNO's matching rules and scoring, with these additional cards:",
              "- A coloured Draw Four makes the next player draw four cards.",
              "- Wild Draw Six and Wild Draw Ten combine a colour choice with the named draw penalty.",
              "- Wild Reverse Draw Four reverses play and gives four cards to the player whose turn it now is. With two players, the penalty comes back to the person who played it.",
              "- Skip Everyone gives you another turn immediately.",
              "- Discard All removes the other cards of its colour from your hand as well.",
              "- Colour Roulette makes the next player draw until they get a non-wild card of the colour you chose. Their turn then ends.",
              "A response to a fixed-number draw penalty must be in the same group as the attack: coloured cards respond to coloured cards, and wilds to wilds. Its penalty must be at least as large as that of the last card played. A coloured Draw Two cannot answer a coloured Draw Four, for example.",
              "With advanced responses enabled, Skip Everyone and Discard All cancel a fixed-number draw penalty completely.",
              "Reaching 25 cards in your hand eliminates you from the current round and gives you 250 penalty points. You return for the next round unless those points take you to the game's elimination limit. The hand-size limit can be changed, or disabled by setting it to zero."),
            rule_section(:flip, "Flip",
              "UNO Flip cards have a light side and a dark side. Play starts on the light side. A Flip card turns over everyone's hand and both piles, so the bottom cards of the piles become the top cards. From then on, match the new sides.",
              "The sides have different special cards:",
              "- The light side includes coloured Draw One cards and Wild Draw Two cards.",
              "- The dark side uses different colours and includes coloured Draw Five cards. Skip Everyone gives the player another turn.",
              "- The dark Wild Draw Colour makes the next player draw until they receive a non-wild card of the chosen colour, then ends their turn.",
              "Special-card scoring stays the same: 20 points for coloured cards and 50 for wilds."),
            rule_section(:extra_rules, "Interceptions and other options",
              "You can also enable these rules before starting:",
              "- Interception lets you play out of turn when you have an identical non-wild copy of the top card. Select it and press Enter. You take over the turn, and the card's effect applies to the next player. An unsuccessful attempt costs three penalty points. Super interception allows the same number or symbol in a different colour; it requires ordinary interception to be enabled too.",
              "- Straights let you follow your own play with consecutive numbers of the same colour, moving up or down. After a green five, for example, quickly play a six and seven. Select and play each card separately with Enter. Keep the same direction and finish before someone else plays.",
              "- Hand swapping makes a seven swap your whole hand with an opponent chosen using the arrows and Enter. A zero passes everyone's hand to the next player in the current direction. If the zero or seven was your last card, the person receiving your empty hand wins the round.",
              "- Buzzers add eight cards to the Classic or No Mercy deck. When one is played, everyone presses B. The last player to respond draws two cards, and any card may be played next. If the buzzer was someone's last card, the round ends after everyone has responded. Flip has no buzzer cards.",
              "- A turn time limit makes a player who runs out of time draw the pending penalty, or one card if there is none, and lose their turn. Choosing a colour and responding to a buzzer pause the timer."),
            rule_section(:controls, "Keyboard shortcuts",
              "Arrow keys: browse cards or choose a colour.",
              "Enter: play a card or confirm a colour or player.",
              "Space: draw a card or accept a draw penalty.",
              "U: call uno or catch someone who did not.",
              "B: respond to a buzzer.",
              "F: challenge Wild Draw Four.",
              "C: read the top card.",
              "V: read the current colour.",
              "E: read players' card counts.",
              "G: read the pending penalty.",
              "Z: find the next legal card on your turn; unavailable with straights, interceptions or buzzers.",
              "Shift+Z: find the previous legal card on your turn; unavailable with straights, interceptions or buzzers.",
              "S: read the scores.",
              "T: announce whose turn it is.",
              "Shift+C: sort by colour; press again to reverse.",
              "Shift+H: sort by value; press again to reverse.",
              "Shift+D: restore the order in which you received the cards.",
              "Shift+M: restore the order in which you received the cards.")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo",
              "En UNO intentas quedarte sin cartas antes que nadie. Al acabar cada ronda, las que conserves te dan puntos de penalizaci\u00F3n. Quien alcanza el l\u00EDmite queda eliminado; la \u00FAltima persona que siga jugando gana la partida.",
              "Juegan de dos a ocho personas. Cada una recibe siete cartas y empieza quien sigue al repartidor."),
            rule_section(:turn, "Jugar y robar",
              "Consulta la carta de la mesa con C. Debes coincidir con su color, n\u00FAmero o s\u00EDmbolo. Sobre un seis azul puedes jugar otra azul o un seis de otro color. Recorre tu mano con las flechas y pulsa Enter para jugar.",
              "Una jugada normal pasa el turno. Si no puedes jugar, roba con Espacio. Despu\u00E9s puedes usar cualquier carta v\u00E1lida de tu mano, incluso una que ya tuvieras. Si tras robar ninguna carta encaja, tu turno termina autom\u00E1ticamente.",
              "Tambi\u00E9n puedes robar en lugar de jugar una carta v\u00E1lida, hasta tres veces en un turno. Tras el tercer robo debes jugar si puedes.",
              "Si se agotan las cartas para robar, se barajan las jugadas anteriormente y vuelven a usarse."),
            rule_section(:special, "Cartas especiales",
              "Adem\u00E1s de n\u00FAmeros, hay cartas con estos efectos:",
              "- Salta turno: el siguiente jugador pierde el turno.",
              "- Cambio de sentido: invierte el orden. Con dos personas act\u00FAa como Salta turno, as\u00ED que vuelve a jugar quien la puso.",
              "- Comod\u00EDn: permite elegir color sin tener que coincidir con el anterior. Despu\u00E9s de jugarlo, elige con las flechas y confirma con Enter. V recuerda el color elegido.",
              "- Roba dos: el siguiente debe robar dos o responder con otro Roba dos. Si responde, la penalizaci\u00F3n sube a cuatro y pasa al siguiente. Las respuestas posteriores la siguen aumentando.",
              "- Comod\u00EDn Roba cuatro: permite elegir color y obliga a robar cuatro. Se responde con otro comod\u00EDn Roba cuatro. Roba dos y Roba cuatro no se acumulan entre s\u00ED.",
              "Para aceptar la penalizaci\u00F3n, pulsa Espacio: robas todas las cartas exigidas. Puedes consultar la cantidad antes con G. Despu\u00E9s a\u00FAn puedes jugar una carta v\u00E1lida; si no tienes ninguna, termina tu turno."),
            rule_section(:ending, "Decir uno y puntuar",
              "Cuando te quede una carta, pulsa U para decir \u00ABuno\u00BB. Si alguien lo olvida, un rival puede pillarlo con esa misma tecla antes de la siguiente carta jugada o robada. El infractor recibe dos cartas.",
              "Jugar la \u00FAltima carta gana la ronda. Si obliga a robar, primero se resuelve esa penalizaci\u00F3n. El ganador recibe cero puntos; los dem\u00E1s cuentan sus cartas restantes:",
              "- Cada carta num\u00E9rica vale su n\u00FAmero en puntos de penalizaci\u00F3n.",
              "- Cada carta especial de color vale 20.",
              "- Cada comod\u00EDn vale 50.",
              "Despu\u00E9s de la ronda queda eliminado quien tenga al menos 500 puntos. Los dem\u00E1s reciben cartas nuevas para otra ronda. Gana la \u00FAltima persona que permanezca. S consulta los resultados."),
            rule_section(:drawing_options, "Variantes de robo y penalizaci\u00F3n",
              "Los apartados siguientes describen opciones que se eligen antes de jugar. El robo y la puntuaci\u00F3n admiten estos cambios:",
              "- Un l\u00EDmite de puntos distinto de 500. Alcanzarlo elimina al jugador despu\u00E9s de la ronda.",
              "- Prohibir robar si ya tienes una carta v\u00E1lida o cambiar el m\u00E1ximo de robos normales por turno.",
              "- Robar hasta poder jugar: una pulsaci\u00F3n de Espacio sigue robando hasta encontrar una carta v\u00E1lida o agotar las disponibles. No cambia las cantidades de las penalizaciones.",
              "- Sin respuestas a penalizaciones, el jugador atacado debe robar; no puede pasar el ataque con otra carta.",
              "- Puedes hacer que aceptar una penalizaci\u00F3n quite siempre el resto del turno.",
              "- Las respuestas avanzadas permiten que Salta turno o un comod\u00EDn normal pasen la penalizaci\u00F3n sin aumentarla. Cambio de sentido la devuelve en sentido contrario. Requiere permitir respuestas a penalizaciones."),
            rule_section(:challenge, "Desafiar un Roba cuatro",
              "En UNO cl\u00E1sico puedes activar el desaf\u00EDo de faroles. Entonces solo puedes jugar un comod\u00EDn Roba cuatro sin consecuencias si no tienes otra carta del color anterior.",
              "Si recibes ese ataque, pulsa F para comprobar la mano de quien lo jug\u00F3. Si ten\u00EDa ese color, \u00E9l roba cuatro. Si no lo ten\u00EDa, t\u00FA robas seis y pierdes el turno."),
            rule_section(:decks, "Elegir baraja",
              "Hay tres barajas disponibles en los ajustes:",
              "- Cl\u00E1sica: usa las reglas explicadas al principio.",
              "- No Mercy: a\u00F1ade ataques m\u00E1s fuertes y eliminaci\u00F3n de la ronda por exceso de cartas. Se explica a continuaci\u00F3n.",
              "- Flip: cada carta tiene dos caras y una carta Flip cambia la cara con la que se juega. Se explica despu\u00E9s de No Mercy."),
            rule_section(:no_mercy, "No Mercy",
              "No Mercy conserva la forma de emparejar y puntuar de UNO cl\u00E1sico, y a\u00F1ade estas cartas:",
              "- Roba cuatro de color: obliga al siguiente a robar cuatro.",
              "- Comodines Roba seis y Roba diez: cambian el color y a\u00F1aden esa cantidad de cartas.",
              "- Comod\u00EDn Cambio de sentido y Roba cuatro: invierte el orden y aplica cuatro cartas a quien tenga ahora el turno. Con dos personas, la penalizaci\u00F3n vuelve a quien lo jug\u00F3.",
              "- Salta a todos: vuelves a jugar inmediatamente.",
              "- Descarta todas: elimina tambi\u00E9n de tu mano las dem\u00E1s cartas de su color.",
              "- Comod\u00EDn Ruleta de colores: el siguiente roba hasta encontrar la primera carta no comod\u00EDn del color que elijas. Despu\u00E9s termina su turno.",
              "Para responder a un robo de cantidad fija, la carta debe ser del mismo grupo que el ataque: de color contra una de color, o comod\u00EDn contra comod\u00EDn. Adem\u00E1s debe ser al menos tan fuerte como la \u00FAltima carta jugada. No puedes responder a un Roba cuatro de color con Roba dos.",
              "Con respuestas avanzadas, Salta a todos y Descarta todas anulan por completo una penalizaci\u00F3n de robo de cantidad fija.",
              "Llegar a 25 cartas te elimina de la ronda y da 250 puntos de penalizaci\u00F3n. Vuelves en la siguiente ronda salvo que ya hayas alcanzado el l\u00EDmite de eliminaci\u00F3n de la partida. Puedes cambiar el l\u00EDmite de 25 cartas o ponerlo a cero para desactivarlo."),
            rule_section(:flip, "Flip",
              "Las cartas tienen una cara clara y otra oscura. Se empieza por la clara. Una carta Voltea da la vuelta a todas las manos y a ambos montones; sus fondos pasan a quedar arriba. Desde entonces se juega seg\u00FAn la nueva cara.",
              "Cada cara tiene cartas especiales distintas:",
              "- La clara incluye Roba uno de color y comodines Roba dos.",
              "- La oscura tiene otros colores y Roba cinco de color. Salta a todos da otra jugada a quien lo usa.",
              "- El comod\u00EDn oscuro Roba hasta el color obliga al siguiente a robar hasta la primera carta no comod\u00EDn del color indicado. Despu\u00E9s pierde el resto del turno.",
              "Las cartas especiales siguen valiendo 20 si son de color y 50 si son comodines."),
            rule_section(:extra_rules, "Intercepciones y otros a\u00F1adidos",
              "Antes de jugar puedes activar tambi\u00E9n estas reglas:",
              "- Intercepci\u00F3n: puedes jugar fuera de turno una carta no comod\u00EDn id\u00E9ntica a la \u00FAltima. El\u00EDgela y pulsa Enter. Tomas el turno y su efecto se aplica al siguiente jugador. Fallar una intercepci\u00F3n cuesta tres puntos de penalizaci\u00F3n. La superintercepci\u00F3n solo exige igual n\u00FAmero o s\u00EDmbolo, no color; requiere tener activadas las intercepciones.",
              "- Escaleras: despu\u00E9s de una carta tuya puedes encadenar n\u00FAmeros consecutivos del mismo color, en orden ascendente o descendente. Tras un cinco verde puedes jugar deprisa seis y siete. Selecciona y juega cada una por separado con Enter, manteniendo la direcci\u00F3n elegida y antes de que juegue otro.",
              "- Intercambio de manos: el siete permite elegir un rival con las flechas y Enter e intercambiar todas las cartas. El cero pasa cada mano al siguiente jugador en el sentido de juego. Si era tu \u00FAltima carta, entregas una mano vac\u00EDa: quien la recibe gana la ronda.",
              "- Cartas de pulsador: se a\u00F1aden ocho al mazo cl\u00E1sico o al de No Mercy. Cuando se juega una, todos pulsan B y el \u00FAltimo roba dos cartas. Despu\u00E9s se puede jugar cualquier carta. Si era la \u00FAltima carta de alguien, la ronda espera a que todos reaccionen antes de terminar. Flip no admite estas cartas.",
              "- Tiempo de turno: quien agote el plazo roba la penalizaci\u00F3n pendiente o, si no hay ninguna, una carta, y pierde el turno. Elegir color y responder a un pulsador detienen la cuenta atr\u00E1s."),
            rule_section(:controls, "Teclas de referencia",
              "Flechas: recorrer cartas o colores.",
              "Enter: jugar una carta o confirmar color o jugador.",
              "Espacio: robar o aceptar una penalizaci\u00F3n de robo.",
              "U: decir uno o denunciar a quien lo olvid\u00F3.",
              "B: responder al pulsador.",
              "F: desafiar un comod\u00EDn Roba cuatro.",
              "C: consultar la carta de la mesa.",
              "V: consultar el color actual.",
              "E: contar las cartas de los jugadores.",
              "G: consultar la penalizaci\u00F3n pendiente.",
              "Z: ir a la siguiente carta legal en tu turno; no est\u00E1 disponible con escaleras, intercepciones o cartas de pulsador.",
              "Shift+Z: ir a la carta legal anterior en tu turno; no est\u00E1 disponible con escaleras, intercepciones o cartas de pulsador.",
              "S: consultar los resultados.",
              "T: consultar de qui\u00E9n es el turno.",
              "Shift+C: ordenar por color; repetir para invertir el orden.",
              "Shift+H: ordenar por valor; repetir para invertir el orden.",
              "Shift+D: recuperar el orden de recepci\u00F3n.",
              "Shift+M: recuperar el orden de recepci\u00F3n.")
          ]
        when "pl"
          [
            rule_section(:aim, "Cel gry",
              "W UNO starasz si\u0119 jako pierwszy pozby\u0107 wszystkich kart. Za karty, kt\u00F3re zostan\u0105 ci na koniec rundy, dostajesz punkty karne. Po osi\u0105gni\u0119ciu limitu punkt\u00F3w odpadasz. Je\u015Bli w grze zostanie ju\u017C tylko jedna osoba, wygrywa ca\u0142\u0105 parti\u0119.",
              "Gra od dw\u00F3ch do o\u015Bmiu os\u00F3b. Ka\u017Cdy zaczyna z siedmioma kartami, a pierwsza tura nale\u017Cy do osoby po rozdaj\u0105cym."),
            rule_section(:turn, "Przebieg tury",
              "Na pocz\u0105tku sprawd\u017A przez C ostatni\u0105 zagran\u0105 kart\u0119. Musisz dopasowa\u0107 do niej kolor, numer albo symbol. Je\u017Celi le\u017Cy niebieska sz\u00F3stka, mo\u017Cesz zagra\u0107 niebiesk\u0105 kart\u0119 lub sz\u00F3stk\u0119 innego koloru. Przejrzyj r\u0119k\u0119 strza\u0142kami i naci\u015Bnij Enter na wybranej karcie.",
              "Po zwyk\u0142ym zagraniu ruch przechodzi dalej. Je\u017Celi nie masz czym zagra\u0107, dobierz kart\u0119 Spacj\u0105. Potem mo\u017Cesz wykorzysta\u0107 dowoln\u0105 pasuj\u0105c\u0105 kart\u0119 z r\u0119ki, tak\u017Ce tak\u0105, kt\u00F3r\u0105 mia\u0142e\u015B wcze\u015Bniej. Je\u015Bli po dobraniu w ca\u0142ej r\u0119ce nadal nie ma legalnego zagrania, tura ko\u0144czy si\u0119 od razu.",
              "Mo\u017Cesz te\u017C dobiera\u0107 zamiast zagrywa\u0107 pasuj\u0105c\u0105 kart\u0119, ale najwy\u017Cej trzy razy w jednej turze. Po trzecim dobraniu musisz zagra\u0107, je\u015Bli masz czym.",
              "Gdy sko\u0144cz\u0105 si\u0119 karty do dobierania, wcze\u015Bniej zagrane karty zostaj\u0105 przetasowane i mo\u017Cna je dobiera\u0107 ponownie."),
            rule_section(:special, "Karty specjalne",
              "Opr\u00F3cz kart z numerami spotkasz karty specjalne:",
              "- \u201EPomi\u0144\u201D odbiera ruch nast\u0119pnej osobie.",
              "- \u201EZmiana kierunku\u201D sprawia, \u017Ce gracie dalej w przeciwn\u0105 stron\u0119. Przy dw\u00F3ch osobach dzia\u0142a jak pomini\u0119cie: zagrywaj\u0105cy dostaje nast\u0119pn\u0105 tur\u0119.",
              "- Dzika karta pozwala wybra\u0107 nowy kolor. Po jej zagraniu wybierz go strza\u0142kami i zatwierd\u017A Enterem. Nie musisz dopasowywa\u0107 dzikiej karty do poprzedniego koloru. Wybrany kolor przypomina klawisz V.",
              "- \u201EDobierz dwie\u201D, czyli plus dwa, atakuje nast\u0119pn\u0105 osob\u0119. Musi ona dobra\u0107 dwie karty albo odpowiedzie\u0107 w\u0142asnym plus dwa. Po odpowiedzi kara ro\u015Bnie do czterech i przechodzi na kolejnego gracza. Nast\u0119pne odpowiedzi zwi\u0119kszaj\u0105 j\u0105 w ten sam spos\u00F3b.",
              "- Dzika plus cztery \u0142\u0105czy wyb\u00F3r koloru z kar\u0105 czterech kart. Na ni\u0105 mo\u017Cna odpowiedzie\u0107 kolejn\u0105 dzik\u0105 plus cztery. Plus dwa i plus cztery nie \u0142\u0105cz\u0105 si\u0119 ze sob\u0105.",
              "\u017Beby przyj\u0105\u0107 kar\u0119, naci\u015Bnij Spacj\u0119. Dobierzesz wszystkie wymagane karty; ich liczb\u0119 mo\u017Cesz wcze\u015Bniej sprawdzi\u0107 klawiszem G. Potem mo\u017Cesz jeszcze zagra\u0107 pasuj\u0105c\u0105 kart\u0119. Je\u015Bli \u017Cadnej nie masz, twoja tura si\u0119 ko\u0144czy."),
            rule_section(:ending, "Uno i punktacja",
              "Kiedy zostanie ci jedna karta, naci\u015Bnij U, \u017Ceby powiedzie\u0107 \u201Euno\u201D. Je\u015Bli kto\u015B o tym zapomni, przeciwnik mo\u017Ce z\u0142apa\u0107 go tym samym klawiszem, zanim nast\u0105pi kolejne zagranie lub dobranie. Przy\u0142apany gracz dostaje dwie dodatkowe karty.",
              "Wy\u0142o\u017Cenie ostatniej karty daje wygran\u0105 w rundzie. Je\u015Bli by\u0142a to karta nakazuj\u0105ca dobieranie, najpierw trzeba rozliczy\u0107 jej kar\u0119. Zwyci\u0119zca nie dostaje punkt\u00F3w, a pozostali licz\u0105 karty w swoich r\u0119kach:",
              "- Karta z numerem daje tyle punkt\u00F3w karnych, ile wskazuje jej warto\u015B\u0107.",
              "- Kolorowa karta specjalna daje 20 punkt\u00F3w karnych.",
              "- Dzika karta daje 50 punkt\u00F3w karnych.",
              "Po rundzie odpada ka\u017Cdy, kto ma co najmniej 500 punkt\u00F3w. Pozostali rozpoczynaj\u0105 kolejn\u0105 z nowymi kartami. Kiedy zostanie tylko jedna osoba, wygrywa ca\u0142\u0105 parti\u0119. S odczytuje wyniki."),
            rule_section(:drawing_options, "Warianty dobierania i kar",
              "Dalsze rozdzia\u0142y opisuj\u0105 dodatki wybierane w ustawieniach sto\u0142u przed gr\u0105. Dobieranie i punktacj\u0119 mo\u017Cna zmieni\u0107 na kilka sposob\u00F3w:",
              "- Mo\u017Cna ustali\u0107 inny limit punkt\u00F3w karnych ni\u017C 500. Po jego osi\u0105gni\u0119ciu gracz odpada po zako\u0144czeniu rundy.",
              "- Mo\u017Cna zabroni\u0107 dobierania z pasuj\u0105c\u0105 kart\u0105 albo zmieni\u0107 maksymaln\u0105 liczb\u0119 zwyk\u0142ych dobra\u0144 w turze.",
              "- Dobieranie do skutku zast\u0119puje pojedyncze dobranie szukaniem pasuj\u0105cej karty. Naciskasz Spacj\u0119 raz i dobierasz do chwili, gdy pojawi si\u0119 karta do zagrania lub sko\u0144cz\u0105 si\u0119 dost\u0119pne karty. Wielko\u015B\u0107 kar pozostaje bez zmiany.",
              "- Wy\u0142\u0105czenie odpowiadania na kary oznacza, \u017Ce zaatakowany gracz musi dobra\u0107. Nie przeka\u017Ce kary w\u0142asn\u0105 kart\u0105.",
              "- Mo\u017Cna ustali\u0107, \u017Ce przyj\u0119cie kary zawsze odbiera reszt\u0119 tury.",
              "- Odpowiedzi zaawansowane pozwalaj\u0105 karcie pomini\u0119cia lub zwyk\u0142ej dzikiej przekaza\u0107 kar\u0119 dalej bez zwi\u0119kszania jej. Zmiana kierunku odsy\u0142a kar\u0119 w drug\u0105 stron\u0119. Ten dodatek wymaga w\u0142\u0105czonego odpowiadania na kary."),
            rule_section(:challenge, "Sprawdzanie dzikiej plus cztery",
              "W klasycznym UNO mo\u017Cecie w\u0142\u0105czy\u0107 sprawdzanie blefu. Dzik\u0105 plus cztery wolno wtedy zagra\u0107 bez konsekwencji tylko wtedy, gdy nie masz innej karty w dotychczasowym kolorze.",
              "Je\u015Bli kto\u015B zaatakuje ci\u0119 tak\u0105 kart\u0105, mo\u017Cesz nacisn\u0105\u0107 F, \u017Ceby sprawdzi\u0107 jego r\u0119k\u0119. Gdy mia\u0142 pasuj\u0105cy kolor, sam dobiera cztery. Gdy go nie mia\u0142, ty dobierasz sze\u015B\u0107 i tracisz tur\u0119."),
            rule_section(:decks, "Wyb\u00F3r talii",
              "W ustawieniach sto\u0142u mo\u017Cna wybra\u0107 jedn\u0105 z trzech talii:",
              "- Klasyczna talia s\u0142u\u017Cy do gry opisanej na pocz\u0105tku tych zasad.",
              "- No Mercy dodaje silniejsze ataki i odpadanie z rundy za zbyt du\u017C\u0105 liczb\u0119 kart w r\u0119ce. Szczeg\u00F3\u0142y znajdziesz w nast\u0119pnym rozdziale.",
              "- Flip ma karty z dwiema r\u00F3\u017Cnymi stronami. Zagranie karty Flip zmienia stron\u0119, kt\u00F3r\u0105 gracie; ten wariant opisano po No Mercy."),
            rule_section(:no_mercy, "Talia No Mercy",
              "No Mercy zachowuje dopasowywanie kart i punktacj\u0119 klasycznego UNO, ale dodaje nast\u0119puj\u0105ce karty:",
              "- Kolorowe plus cztery nakazuje nast\u0119pnemu graczowi dobra\u0107 cztery karty.",
              "- Dzikie plus sze\u015B\u0107 i plus dziesi\u0119\u0107 \u0142\u0105cz\u0105 wyb\u00F3r koloru z odpowiedni\u0105 kar\u0105 dobierania.",
              "- Dzika zmiana kierunku z plus cztery zmienia kierunek gry i nak\u0142ada kar\u0119 czterech kart na gracza, kt\u00F3ry ma teraz tur\u0119. Przy dw\u00F3ch osobach kara wraca do zagrywaj\u0105cego.",
              "- Po karcie \u201EPomi\u0144 wszystkich\u201D od razu grasz ponownie.",
              "- \u201EOdrzu\u0107 wszystkie\u201D usuwa z r\u0119ki r\u00F3wnie\u017C pozosta\u0142e karty swojego koloru.",
              "- \u201ERuletka kolor\u00F3w\u201D ka\u017Ce nast\u0119pnemu graczowi dobiera\u0107 a\u017C do pierwszej niedzikiej karty wybranego przez ciebie koloru. Po tym dobieraniu jego tura si\u0119 ko\u0144czy.",
              "Odpowied\u017A na kar\u0119 okre\u015Blonej liczby kart musi nale\u017Ce\u0107 do tej samej grupy co atak: kolorowa na kolorow\u0105, dzika na dzik\u0105. Musi te\u017C by\u0107 co najmniej tak silna jak ostatnio zagrana karta. Na przyk\u0142ad na kolorowe plus cztery nie mo\u017Cna odpowiedzie\u0107 plus dwa.",
              "Je\u015Bli w\u0142\u0105czono odpowiedzi zaawansowane, \u201EPomi\u0144 wszystkich\u201D i \u201EOdrzu\u0107 wszystkie\u201D pozwalaj\u0105 ca\u0142kiem anulowa\u0107 kar\u0119 dobrania okre\u015Blonej liczby kart.",
              "Gdy uzbierasz w r\u0119ce 25 kart, odpadasz z bie\u017C\u0105cej rundy i otrzymujesz 250 punkt\u00F3w karnych. Wracasz w nast\u0119pnej rundzie, chyba \u017Ce osi\u0105gn\u0105\u0142e\u015B ju\u017C limit punkt\u00F3w oznaczaj\u0105cy przegran\u0105 w ca\u0142ej partii. W ustawieniach mo\u017Cna zmieni\u0107 limit 25 kart lub wy\u0142\u0105czy\u0107 go warto\u015Bci\u0105 zero."),
            rule_section(:flip, "Talia Flip",
              "W UNO Flip karty maj\u0105 dwie strony: jasn\u0105 i ciemn\u0105. Gra zaczyna si\u0119 po jasnej. Karta Flip odwraca wszystkie r\u0119ce i obie talie; dotychczasowe spody stos\u00F3w staj\u0105 si\u0119 ich wierzchami. Od tej chwili dopasowujecie karty wed\u0142ug nowej strony.",
              "Obie strony maj\u0105 inne karty specjalne:",
              "- Po jasnej stronie s\u0105 mi\u0119dzy innymi kolorowe plus jeden oraz dzikie plus dwa.",
              "- Po ciemnej stronie pojawiaj\u0105 si\u0119 inne kolory i kolorowe plus pi\u0119\u0107. Pomini\u0119cie wszystkich daje zagrywaj\u0105cemu kolejn\u0105 tur\u0119.",
              "- Ciemna dzika karta dobierania do koloru ka\u017Ce nast\u0119pnemu graczowi dobiera\u0107 do pierwszej niedzikiej karty wskazanego koloru. Po tym traci reszt\u0119 tury.",
              "Punktacja kart specjalnych pozostaje taka sama: kolorowe s\u0105 warte 20, a dzikie 50 punkt\u00F3w."),
            rule_section(:extra_rules, "Przechwytywanie i inne dodatki",
              "Przed gr\u0105 mo\u017Cna te\u017C w\u0142\u0105czy\u0107 poni\u017Csze dodatki:",
              "- Przechwytywanie pozwala zagra\u0107 podczas cudzej tury identyczn\u0105 niedzik\u0105 kart\u0119 jak ostatnia na stole. Wybierz j\u0105 i naci\u015Bnij Enter. Przejmujesz kolejk\u0119, a dzia\u0142anie tej karty obowi\u0105zuje nast\u0119pnego gracza. Nieudana pr\u00F3ba przechwycenia kosztuje trzy punkty karne. Przy superprzechwytywaniu wystarczy ten sam numer lub symbol; kolor nie musi si\u0119 zgadza\u0107. Superprzechwytywanie wymaga zwyk\u0142ego przechwytywania.",
              "- Strity pozwalaj\u0105 po w\u0142asnym zagraniu dok\u0142ada\u0107 kolejne numery w tym samym kolorze, rosn\u0105co albo malej\u0105co. Na przyk\u0142ad po zielonej pi\u0105tce mo\u017Cesz szybko zagra\u0107 sz\u00F3stk\u0119 i si\u00F3demk\u0119. Ka\u017Cd\u0105 kart\u0119 wybierasz i zagrywasz osobno Enterem. Zachowaj wybrany kierunek i zd\u0105\u017C, zanim zagra kto\u015B inny.",
              "- Przy zamianach r\u0105k si\u00F3demka pozwala wskaza\u0107 przeciwnika strza\u0142kami i Enterem, a nast\u0119pnie wymieni\u0107 z nim wszystkie karty. Po zerze ka\u017Cdy oddaje r\u0119k\u0119 nast\u0119pnej osobie zgodnie z kierunkiem gry. Gdy zero lub si\u00F3demka by\u0142y twoj\u0105 ostatni\u0105 kart\u0105, oddajesz komu\u015B pust\u0105 r\u0119k\u0119: to ta osoba wygrywa rund\u0119.",
              "- Brz\u0119czyki dodaj\u0105 osiem kart do talii klasycznej albo No Mercy. Po zagraniu brz\u0119czyka wszyscy naciskaj\u0105 B. Ostatni gracz dobiera dwie karty. Dalej mo\u017Cna zagra\u0107 dowoln\u0105 kart\u0119; je\u017Celi brz\u0119czyk by\u0142 ostatni\u0105 kart\u0105 gracza, dopiero po reakcji wszystkich ko\u0144czy si\u0119 runda. We Flip nie ma brz\u0119czyk\u00F3w.",
              "- Mo\u017Cecie w\u0142\u0105czy\u0107 czas na tur\u0119. Kto nie zd\u0105\u017Cy, dobiera oczekuj\u0105c\u0105 kar\u0119, a je\u015Bli jej nie ma \u2014 jedn\u0105 kart\u0119, i traci tur\u0119. Wybieranie koloru oraz reakcja na brz\u0119czyk zatrzymuj\u0105 odliczanie."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: przegl\u0105daj karty lub kolory do wyboru.",
              "Enter: zagraj kart\u0119 albo potwierd\u017A wyb\u00F3r koloru lub gracza.",
              "Spacja: dobierz kart\u0119 lub przyjmij kar\u0119 dobierania.",
              "U: powiedz uno lub z\u0142ap gracza, kt\u00F3ry go nie powiedzia\u0142.",
              "B: zareaguj na brz\u0119czyk.",
              "F: zakwestionuj zagranie dzikiej karty plus cztery.",
              "C: odczytaj kart\u0119 na stole.",
              "V: odczytaj obecny kolor.",
              "E: odczytaj liczby kart graczy.",
              "G: odczytaj oczekuj\u0105c\u0105 kar\u0119.",
              "Z: przejd\u017A do nast\u0119pnej legalnej karty we w\u0142asnej turze; niedost\u0119pne przy stritach, przechwytywaniu lub brz\u0119czykach.",
              "Shift+Z: przejd\u017A do poprzedniej legalnej karty we w\u0142asnej turze; niedost\u0119pne przy stritach, przechwytywaniu lub brz\u0119czykach.",
              "S: odczytaj wyniki.",
              "T: odczytaj, czyja jest tura.",
              "Shift+C: sortuj karty wed\u0142ug koloru; ponowne u\u017Cycie odwraca kolejno\u015B\u0107.",
              "Shift+H: sortuj karty wed\u0142ug warto\u015Bci; ponowne u\u017Cycie odwraca kolejno\u015B\u0107.",
              "Shift+D: przywr\u00F3\u0107 kolejno\u015B\u0107 otrzymania kart.",
              "Shift+M: przywr\u00F3\u0107 kolejno\u015B\u0107 otrzymania kart.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0423\u041D\u041E \u043D\u0443\u0436\u043D\u043E \u0440\u0430\u043D\u044C\u0448\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u0438\u0437\u0431\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u043E\u0442 \u043A\u0430\u0440\u0442. \u041E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043D\u0430 \u0440\u0443\u043A\u0430\u0445 \u0432 \u043A\u043E\u043D\u0446\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u043A\u0430\u0440\u0442\u044B \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0435 \u043E\u0447\u043A\u0438. \u041F\u043E \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0438 \u043F\u0440\u0435\u0434\u0435\u043B\u0430 \u0438\u0433\u0440\u043E\u043A \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442, \u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u044E \u043F\u0430\u0440\u0442\u0438\u044E.",
              "\u0418\u0433\u0440\u0430\u044E\u0442 \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0447\u0435\u043B\u043E\u0432\u0435\u043A. \u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0441\u0435\u043C\u044C \u043A\u0430\u0440\u0442. \u041F\u0435\u0440\u0432\u044B\u043C \u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043F\u043E\u0441\u043B\u0435 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E."),
            rule_section(:turn, "\u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0445\u043E\u0434",
              "\u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0441 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 C: \u043E\u043D\u0430 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0432\u0435\u0440\u0445\u043D\u044E\u044E \u043A\u0430\u0440\u0442\u0443 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u0412\u0430\u0448\u0430 \u043A\u0430\u0440\u0442\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u0442\u044C \u0441 \u043D\u0435\u0439 \u043F\u043E \u0446\u0432\u0435\u0442\u0443, \u0447\u0438\u0441\u043B\u0443 \u0438\u043B\u0438 \u0441\u0438\u043C\u0432\u043E\u043B\u0443. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043D\u0430 \u0441\u0438\u043D\u044E\u044E \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0443 \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u043B\u044E\u0431\u0430\u044F \u0441\u0438\u043D\u044F\u044F \u043A\u0430\u0440\u0442\u0430 \u0438\u043B\u0438 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0430 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0446\u0432\u0435\u0442\u0430. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter.",
              "\u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430 \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0434\u0430\u043B\u044C\u0448\u0435. \u0415\u0441\u043B\u0438 \u0445\u043E\u0434\u0438\u0442\u044C \u043D\u0435\u0447\u0435\u043C, \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. \u041F\u043E\u0441\u043B\u0435 \u0434\u043E\u0431\u043E\u0440\u0430 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0441 \u0440\u0443\u043A\u0438, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0438\u043C\u0435\u0432\u0448\u0443\u044E\u0441\u044F \u0440\u0430\u043D\u044C\u0448\u0435. \u0415\u0441\u043B\u0438 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0445 \u043D\u0435\u0442 \u0432\u043E\u043E\u0431\u0449\u0435, \u0445\u043E\u0434 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F.",
              "\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0438 \u0432\u043C\u0435\u0441\u0442\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0433\u043E \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430, \u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u0442\u0440\u0451\u0445 \u0440\u0430\u0437 \u0437\u0430 \u0445\u043E\u0434. \u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u0434\u043E\u0431\u043E\u0440\u0430 \u043D\u0443\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C, \u0435\u0441\u043B\u0438 \u0435\u0441\u0442\u044C \u0447\u0435\u043C.",
              "\u041A\u043E\u0433\u0434\u0430 \u043A\u043E\u043B\u043E\u0434\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u0440\u0430\u043D\u0435\u0435 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043F\u0435\u0440\u0435\u043C\u0435\u0448\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u0441\u043D\u043E\u0432\u0430 \u0441\u0442\u0430\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0434\u043B\u044F \u0434\u043E\u0431\u043E\u0440\u0430."),
            rule_section(:special, "\u041E\u0441\u043E\u0431\u044B\u0435 \u043A\u0430\u0440\u0442\u044B",
              "\u041A\u0440\u043E\u043C\u0435 \u043A\u0430\u0440\u0442 \u0441 \u0447\u0438\u0441\u043B\u0430\u043C\u0438, \u0432 \u043A\u043E\u043B\u043E\u0434\u0435 \u0435\u0441\u0442\u044C \u043E\u0441\u043E\u0431\u044B\u0435:",
              "- \u00AB\u041F\u0440\u043E\u043F\u0443\u0441\u043A\u00BB \u043B\u0438\u0448\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0445\u043E\u0434\u0430.",
              "- \u00AB\u0420\u0435\u0432\u0435\u0440\u0441\u00BB \u043C\u0435\u043D\u044F\u0435\u0442 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0438\u0433\u0440\u044B. \u0412\u0434\u0432\u043E\u0451\u043C \u043E\u043D \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043A\u0430\u043A \u043F\u0440\u043E\u043F\u0443\u0441\u043A: \u0441\u044B\u0433\u0440\u0430\u0432\u0448\u0438\u0439 \u0445\u043E\u0434\u0438\u0442 \u0435\u0449\u0451 \u0440\u0430\u0437.",
              "- \u0414\u0438\u043A\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0437\u0430\u043A\u0430\u0437\u0430\u0442\u044C \u0446\u0432\u0435\u0442 \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u043F\u0440\u0435\u0436\u043D\u0435\u0433\u043E \u0446\u0432\u0435\u0442\u0430 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u0421\u044B\u0433\u0440\u0430\u0432 \u0435\u0451, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0446\u0432\u0435\u0442 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 V \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0446\u0432\u0435\u0442.",
              "- \u00AB\u0412\u0437\u044F\u0442\u044C \u0434\u0432\u0435\u00BB, \u0438\u043B\u0438 +2, \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0434\u0432\u0435 \u043A\u0430\u0440\u0442\u044B. \u041E\u043D \u043C\u043E\u0436\u0435\u0442 \u0432\u0437\u044F\u0442\u044C \u0438\u0445 \u0438\u043B\u0438 \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u0441\u0432\u043E\u0435\u0439 +2. \u041F\u043E\u0441\u043B\u0435 \u043E\u0442\u0432\u0435\u0442\u0430 \u0448\u0442\u0440\u0430\u0444 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0440\u0430\u0432\u0435\u043D \u0447\u0435\u0442\u044B\u0440\u0451\u043C \u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0434\u0430\u043B\u044C\u0448\u0435. \u041A\u0430\u0436\u0434\u0430\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0430\u044F +2 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0435\u0433\u043E \u0435\u0449\u0451 \u043D\u0430 \u0434\u0432\u0435.",
              "- \u0414\u0438\u043A\u0430\u044F +4 \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u043C\u0435\u043D\u044F\u0435\u0442 \u0446\u0432\u0435\u0442 \u0438 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u043A\u0430\u0440\u0442\u044B. \u041E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u043D\u0430 \u043D\u0435\u0451 \u043C\u043E\u0436\u043D\u043E \u0434\u0440\u0443\u0433\u043E\u0439 \u0434\u0438\u043A\u043E\u0439 +4. \u0428\u0442\u0440\u0430\u0444\u044B +2 \u0438 +4 \u043C\u0435\u0436\u0434\u0443 \u0441\u043E\u0431\u043E\u0439 \u043D\u0435 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F.",
              "\u0427\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0448\u0442\u0440\u0430\u0444, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u041F\u0440\u043E\u0431\u0435\u043B \u0438 \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u0432\u0441\u0451 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E. \u0417\u0430\u0440\u0430\u043D\u0435\u0435 \u0443\u0437\u043D\u0430\u0442\u044C \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 G. \u041F\u043E\u0441\u043B\u0435 \u0448\u0442\u0440\u0430\u0444\u043D\u043E\u0433\u043E \u0434\u043E\u0431\u043E\u0440\u0430 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0435\u0449\u0451 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443. \u0415\u0441\u043B\u0438 \u0442\u0430\u043A\u043E\u0439 \u043D\u0435\u0442, \u0445\u043E\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F."),
            rule_section(:ending, "\u00AB\u0423\u043D\u043E\u00BB, \u043A\u043E\u043D\u0435\u0446 \u0440\u0430\u0443\u043D\u0434\u0430 \u0438 \u043E\u0447\u043A\u0438",
              "\u041E\u0441\u0442\u0430\u0432\u0448\u0438\u0441\u044C \u0441 \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u043E\u0439, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 U, \u0447\u0442\u043E\u0431\u044B \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u00AB\u0443\u043D\u043E\u00BB. \u0417\u0430\u0431\u044B\u0432\u0448\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0439\u043C\u0430\u0442\u044C \u0442\u043E\u0439 \u0436\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 \u0434\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430 \u0438\u043B\u0438 \u0434\u043E\u0431\u043E\u0440\u0430. \u041F\u043E\u0439\u043C\u0430\u043D\u043D\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0434\u0432\u0435 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B.",
              "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u043E\u0431\u0435\u0434\u0443 \u0432 \u0440\u0430\u0443\u043D\u0434\u0435. \u0415\u0441\u043B\u0438 \u043E\u043D\u0430 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0434\u043E\u0431\u043E\u0440, \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0435\u0451 \u0448\u0442\u0440\u0430\u0444. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043D\u043E\u043B\u044C \u043E\u0447\u043A\u043E\u0432, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u0447\u0438\u0442\u0430\u044E\u0442 \u043A\u0430\u0440\u0442\u044B \u043D\u0430 \u0440\u0443\u043A\u0430\u0445:",
              "- \u041A\u0430\u0440\u0442\u0430 \u0441 \u0447\u0438\u0441\u043B\u043E\u043C \u0434\u0430\u0451\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u043D\u0435\u0439 \u0443\u043A\u0430\u0437\u0430\u043D\u043E.",
              "- \u0426\u0432\u0435\u0442\u043D\u0430\u044F \u043E\u0441\u043E\u0431\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0434\u0430\u0451\u0442 20 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0414\u0438\u043A\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0434\u0430\u0451\u0442 50 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432.",
              "\u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u0432\u044B\u0431\u044B\u0432\u0430\u044E\u0442 \u0438\u0433\u0440\u043E\u043A\u0438 \u0441\u043E \u0441\u0447\u0451\u0442\u043E\u043C 500 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043D\u043E\u0432\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0432 \u043F\u0430\u0440\u0442\u0438\u0438. \u0421\u0447\u0451\u0442 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 S."),
            rule_section(:drawing_options, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0434\u043E\u0431\u043E\u0440\u0430 \u0438 \u0448\u0442\u0440\u0430\u0444\u043E\u0432",
              "\u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0440\u0430\u0437\u0434\u0435\u043B\u044B \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F, \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u043C\u044B\u0435 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0434\u043E \u0438\u0433\u0440\u044B. \u0414\u043B\u044F \u0434\u043E\u0431\u043E\u0440\u0430 \u0438 \u0441\u0447\u0451\u0442\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0442\u0430\u043A\u0438\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F:",
              "- \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u044C \u043F\u0440\u0435\u0434\u0435\u043B \u0432 500 \u043E\u0447\u043A\u043E\u0432 \u0434\u0440\u0443\u0433\u0438\u043C. \u0414\u043E\u0441\u0442\u0438\u0433\u0448\u0438\u0439 \u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0440\u0430\u0443\u043D\u0434\u0430.",
              "- \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u043F\u0440\u0435\u0442\u0438\u0442\u044C \u0434\u043E\u0431\u0440\u043E\u0432\u043E\u043B\u044C\u043D\u044B\u0439 \u0434\u043E\u0431\u043E\u0440 \u0441 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0435\u0439 \u043A\u0430\u0440\u0442\u043E\u0439 \u043B\u0438\u0431\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043E\u0431\u044B\u0447\u043D\u044B\u0445 \u0434\u043E\u0431\u043E\u0440\u043E\u0432 \u0437\u0430 \u0445\u043E\u0434.",
              "- \u0414\u043E\u0431\u043E\u0440 \u0434\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0435\u0439 \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u043F\u043E\u0438\u0441\u043A\u043E\u043C: \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u041F\u0440\u043E\u0431\u0435\u043B \u043E\u0434\u0438\u043D \u0440\u0430\u0437, \u0438 \u043A\u0430\u0440\u0442\u044B \u0431\u0443\u0434\u0443\u0442 \u0431\u0440\u0430\u0442\u044C\u0441\u044F \u0434\u043E \u043F\u043E\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0438\u043B\u0438 \u0438\u0441\u0447\u0435\u0440\u043F\u0430\u043D\u0438\u044F \u0437\u0430\u043F\u0430\u0441\u0430. \u0420\u0430\u0437\u043C\u0435\u0440 \u0448\u0442\u0440\u0430\u0444\u043E\u0432 \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F.",
              "- \u0411\u0435\u0437 \u043E\u0442\u0432\u0435\u0442\u043E\u0432 \u043D\u0430 \u0448\u0442\u0440\u0430\u0444\u044B \u0430\u0442\u0430\u043A\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u043E\u0431\u044F\u0437\u0430\u043D \u0432\u0437\u044F\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0438 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u043F\u0435\u0440\u0435\u0434\u0430\u0442\u044C \u0448\u0442\u0440\u0430\u0444 \u0434\u0430\u043B\u044C\u0448\u0435 \u0441\u0432\u043E\u0435\u0439 \u043A\u0430\u0440\u0442\u043E\u0439.",
              "- \u041C\u043E\u0436\u043D\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u0435 \u0445\u043E\u0434\u0430 \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u043D\u044F\u0442\u0438\u044F \u0448\u0442\u0440\u0430\u0444\u0430.",
              "- \u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u043D\u044B\u0435 \u043E\u0442\u0432\u0435\u0442\u044B \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u00AB\u041F\u0440\u043E\u043F\u0443\u0441\u043A\u0443\u00BB \u0438 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0434\u0438\u043A\u043E\u0439 \u043A\u0430\u0440\u0442\u0435 \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0442\u044C \u0448\u0442\u0440\u0430\u0444 \u0434\u0430\u043B\u044C\u0448\u0435, \u043D\u0435 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u044F \u0435\u0433\u043E. \u00AB\u0420\u0435\u0432\u0435\u0440\u0441\u00BB \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0448\u0442\u0440\u0430\u0444 \u0432 \u0434\u0440\u0443\u0433\u0443\u044E \u0441\u0442\u043E\u0440\u043E\u043D\u0443. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0434\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u0442\u044C \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B \u043E\u0442\u0432\u0435\u0442\u044B \u043D\u0430 \u0448\u0442\u0440\u0430\u0444\u044B."),
            rule_section(:challenge, "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0434\u0438\u043A\u043E\u0439 +4",
              "\u0412 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u043A\u043E\u043B\u043E\u0434\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u0431\u043B\u0435\u0444\u0430. \u0422\u043E\u0433\u0434\u0430 \u0434\u0438\u043A\u0443\u044E +4 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442\u0441\u044F \u0431\u0435\u0437\u043D\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043B\u0438\u0448\u044C \u043F\u0440\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0434\u0440\u0443\u0433\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u043F\u0440\u0435\u0436\u043D\u0435\u0433\u043E \u0446\u0432\u0435\u0442\u0430.",
              "\u041F\u043E\u043B\u0443\u0447\u0438\u0432 \u0442\u0430\u043A\u0443\u044E \u0430\u0442\u0430\u043A\u0443, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 F, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0440\u0443\u043A\u0443 \u043D\u0430\u043F\u0430\u0434\u0430\u0432\u0448\u0435\u0433\u043E. \u0415\u0441\u043B\u0438 \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u0446\u0432\u0435\u0442 \u0443 \u043D\u0435\u0433\u043E \u0431\u044B\u043B, \u043E\u043D \u0441\u0430\u043C \u0431\u0435\u0440\u0451\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u043A\u0430\u0440\u0442\u044B. \u0415\u0441\u043B\u0438 \u043D\u0435 \u0431\u044B\u043B, \u0432\u044B \u0431\u0435\u0440\u0451\u0442\u0435 \u0448\u0435\u0441\u0442\u044C \u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0435 \u0445\u043E\u0434."),
            rule_section(:decks, "\u0412\u044B\u0431\u043E\u0440 \u043A\u043E\u043B\u043E\u0434\u044B",
              "\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0442\u0440\u0438 \u043A\u043E\u043B\u043E\u0434\u044B:",
              "- \u041A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u2014 \u0434\u043B\u044F \u0438\u0433\u0440\u044B, \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u043E\u0439 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B.",
              "- No Mercy \u2014 \u0441 \u0431\u043E\u043B\u0435\u0435 \u0441\u0438\u043B\u044C\u043D\u044B\u043C\u0438 \u0430\u0442\u0430\u043A\u0430\u043C\u0438 \u0438 \u0432\u044B\u0431\u044B\u0432\u0430\u043D\u0438\u0435\u043C \u0438\u0437 \u0440\u0430\u0443\u043D\u0434\u0430 \u0437\u0430 \u0441\u043B\u0438\u0448\u043A\u043E\u043C \u0431\u043E\u043B\u044C\u0448\u0443\u044E \u0440\u0443\u043A\u0443. \u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u043F\u0440\u0438\u0432\u0435\u0434\u0435\u043D\u044B \u043D\u0438\u0436\u0435.",
              "- Flip \u2014 \u0441 \u0434\u0432\u0443\u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0438\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438. \u041A\u0430\u0440\u0442\u0430 \u043F\u0435\u0440\u0435\u0432\u043E\u0440\u043E\u0442\u0430 \u043C\u0435\u043D\u044F\u0435\u0442 \u0430\u043A\u0442\u0438\u0432\u043D\u0443\u044E \u0441\u0442\u043E\u0440\u043E\u043D\u0443; \u044D\u0442\u043E\u0442 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u043E\u043F\u0438\u0441\u0430\u043D \u043F\u043E\u0441\u043B\u0435 No Mercy."),
            rule_section(:no_mercy, "No Mercy",
              "\u041F\u043E\u0434\u0431\u043E\u0440 \u043A\u0430\u0440\u0442 \u0438 \u043F\u043E\u0434\u0441\u0447\u0451\u0442 \u043E\u0447\u043A\u043E\u0432 \u0432 No Mercy \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u043C\u0438, \u043D\u043E \u043F\u043E\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043D\u043E\u0432\u044B\u0435 \u043A\u0430\u0440\u0442\u044B:",
              "- \u0426\u0432\u0435\u0442\u043D\u0430\u044F +4 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0447\u0435\u0442\u044B\u0440\u0435 \u043A\u0430\u0440\u0442\u044B.",
              "- \u0414\u0438\u043A\u0438\u0435 +6 \u0438 +10 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0446\u0432\u0435\u0442 \u0438 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u0448\u0435\u0441\u0442\u044C \u0438\u043B\u0438 \u0434\u0435\u0441\u044F\u0442\u044C \u043A\u0430\u0440\u0442.",
              "- \u0414\u0438\u043A\u0430\u044F \u0441\u043C\u0435\u043D\u0430 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u0441 +4 \u0440\u0430\u0437\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0438 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u043A\u0430\u0440\u0442\u044B \u0442\u043E\u043C\u0443, \u0447\u0435\u0439 \u0445\u043E\u0434 \u0442\u0435\u043F\u0435\u0440\u044C \u043D\u0430\u0441\u0442\u0443\u043F\u0438\u043B. \u0412\u0434\u0432\u043E\u0451\u043C \u0448\u0442\u0440\u0430\u0444 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043A \u0441\u044B\u0433\u0440\u0430\u0432\u0448\u0435\u043C\u0443.",
              "- \u00AB\u041F\u0440\u043E\u043F\u0443\u0441\u043A \u0432\u0441\u0435\u0445\u00BB \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0441\u0440\u0430\u0437\u0443 \u0445\u043E\u0434\u0438\u0442\u044C \u0441\u043D\u043E\u0432\u0430.",
              "- \u00AB\u0421\u0431\u0440\u043E\u0441 \u0432\u0441\u0435\u0445\u00BB \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u0438\u0437 \u0440\u0443\u043A\u0438 \u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0441\u0432\u043E\u0435\u0433\u043E \u0446\u0432\u0435\u0442\u0430.",
              "- \u00AB\u0414\u0438\u043A\u0430\u044F \u0446\u0432\u0435\u0442\u043E\u0432\u0430\u044F \u0440\u0443\u043B\u0435\u0442\u043A\u0430\u00BB \u0437\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0439 \u043D\u0435\u0434\u0438\u043A\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0432\u0430\u043C\u0438 \u0446\u0432\u0435\u0442\u0430. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u0435\u0433\u043E \u0445\u043E\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F.",
              "\u041E\u0442\u0432\u0435\u0442 \u043D\u0430 \u0448\u0442\u0440\u0430\u0444 \u0441 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u043C \u0447\u0438\u0441\u043B\u043E\u043C \u043A\u0430\u0440\u0442 \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u0442\u043E\u0433\u043E \u0436\u0435 \u0442\u0438\u043F\u0430: \u0446\u0432\u0435\u0442\u043D\u0430\u044F \u0430\u0442\u0430\u043A\u0430 \u043D\u0430 \u0446\u0432\u0435\u0442\u043D\u0443\u044E, \u0434\u0438\u043A\u0430\u044F \u043D\u0430 \u0434\u0438\u043A\u0443\u044E. \u041A\u0440\u043E\u043C\u0435 \u0442\u043E\u0433\u043E, \u043E\u0442\u0432\u0435\u0442 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0441\u043B\u0430\u0431\u0435\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u043E\u0439 \u0430\u0442\u0430\u043A\u0438. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043D\u0430 \u0446\u0432\u0435\u0442\u043D\u0443\u044E +4 \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C +2.",
              "\u041F\u0440\u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u043D\u044B\u0445 \u043E\u0442\u0432\u0435\u0442\u0430\u0445 \u00AB\u041F\u0440\u043E\u043F\u0443\u0441\u043A \u0432\u0441\u0435\u0445\u00BB \u0438 \u00AB\u0421\u0431\u0440\u043E\u0441 \u0432\u0441\u0435\u0445\u00BB \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u0442\u043C\u0435\u043D\u044F\u044E\u0442 \u0448\u0442\u0440\u0430\u0444 \u0441 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u043C \u0447\u0438\u0441\u043B\u043E\u043C \u043A\u0430\u0440\u0442.",
              "\u041D\u0430\u0431\u0440\u0430\u0432 \u0432 \u0440\u0443\u043A\u0435 25 \u043A\u0430\u0440\u0442, \u0432\u044B \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442\u0435 \u0438\u0437 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0440\u0430\u0443\u043D\u0434\u0430 \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 250 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432. \u0412 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0443\u043D\u0434 \u0432\u044B \u0432\u0435\u0440\u043D\u0451\u0442\u0435\u0441\u044C, \u0435\u0441\u043B\u0438 \u0435\u0449\u0451 \u043D\u0435 \u0434\u043E\u0441\u0442\u0438\u0433\u043B\u0438 \u043E\u0431\u0449\u0435\u0433\u043E \u043F\u0440\u0435\u0434\u0435\u043B\u0430 \u043E\u0447\u043A\u043E\u0432. \u041F\u043E\u0440\u043E\u0433 \u0432 25 \u043A\u0430\u0440\u0442 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u043B\u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C 0."),
            rule_section(:flip, "Flip",
              "\u0412 \u0423\u041D\u041E Flip \u0443 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0441\u0432\u0435\u0442\u043B\u0430\u044F \u0438 \u0442\u0451\u043C\u043D\u0430\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u044B. \u041D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u0441\u043E \u0441\u0432\u0435\u0442\u043B\u043E\u0439. \u041A\u0430\u0440\u0442\u0430 \u043F\u0435\u0440\u0435\u0432\u043E\u0440\u043E\u0442\u0430 \u043F\u0435\u0440\u0435\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0432\u0441\u0435 \u0440\u0443\u043A\u0438 \u0438 \u043E\u0431\u0435 \u0441\u0442\u043E\u043F\u043A\u0438; \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u043D\u0438\u0437 \u043A\u0430\u0436\u0434\u043E\u0439 \u0441\u0442\u043E\u043F\u043A\u0438 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0432\u0435\u0440\u0445\u043E\u043C. \u0414\u0430\u043B\u044C\u0448\u0435 \u043A\u0430\u0440\u0442\u044B \u043F\u043E\u0434\u0431\u0438\u0440\u0430\u044E\u0442 \u0443\u0436\u0435 \u043F\u043E \u043D\u043E\u0432\u043E\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u0435.",
              "\u041D\u0430 \u0441\u0442\u043E\u0440\u043E\u043D\u0430\u0445 \u0440\u0430\u0437\u043D\u044B\u0435 \u043E\u0441\u043E\u0431\u044B\u0435 \u043A\u0430\u0440\u0442\u044B:",
              "- \u041D\u0430 \u0441\u0432\u0435\u0442\u043B\u043E\u0439 \u0435\u0441\u0442\u044C, \u0432 \u0447\u0430\u0441\u0442\u043D\u043E\u0441\u0442\u0438, \u0446\u0432\u0435\u0442\u043D\u0430\u044F +1 \u0438 \u0434\u0438\u043A\u0430\u044F +2.",
              "- \u041D\u0430 \u0442\u0451\u043C\u043D\u043E\u0439 \u043F\u043E\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0434\u0440\u0443\u0433\u0438\u0435 \u0446\u0432\u0435\u0442\u0430 \u0438 \u0446\u0432\u0435\u0442\u043D\u0430\u044F +5. \u00AB\u041F\u0440\u043E\u043F\u0443\u0441\u043A \u0432\u0441\u0435\u0445\u00BB \u0434\u0430\u0451\u0442 \u0441\u044B\u0433\u0440\u0430\u0432\u0448\u0435\u043C\u0443 \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0445\u043E\u0434.",
              "- \u0422\u0451\u043C\u043D\u0430\u044F \u0434\u0438\u043A\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0434\u043E\u0431\u043E\u0440\u0430 \u0434\u043E \u0446\u0432\u0435\u0442\u0430 \u0437\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0431\u0440\u0430\u0442\u044C \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0439 \u043D\u0435\u0434\u0438\u043A\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0446\u0432\u0435\u0442\u0430. \u041F\u043E\u0441\u043B\u0435 \u0434\u043E\u0431\u043E\u0440\u0430 \u043E\u043D \u0442\u0435\u0440\u044F\u0435\u0442 \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0445\u043E\u0434\u0430.",
              "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043E\u0441\u043E\u0431\u044B\u0445 \u043A\u0430\u0440\u0442 \u043F\u0440\u0435\u0436\u043D\u044F\u044F: \u0446\u0432\u0435\u0442\u043D\u044B\u0435 \u2014 20 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432, \u0434\u0438\u043A\u0438\u0435 \u2014 50."),
            rule_section(:extra_rules, "\u041F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u044B \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u0434\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F",
              "\u041F\u0435\u0440\u0435\u0434 \u0438\u0433\u0440\u043E\u0439 \u043C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430:",
              "- \u041F\u0435\u0440\u0435\u0445\u0432\u0430\u0442 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0432 \u0447\u0443\u0436\u043E\u0439 \u0445\u043E\u0434 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043D\u0435\u0434\u0438\u043A\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u044E\u0449\u0443\u044E \u0441 \u0432\u0435\u0440\u0445\u043D\u0435\u0439. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041E\u0447\u0435\u0440\u0435\u0434\u044C \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043A \u0432\u0430\u043C, \u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043A\u0430\u0440\u0442\u044B \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443. \u041D\u0435\u0443\u0434\u0430\u0447\u043D\u0430\u044F \u043F\u043E\u043F\u044B\u0442\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 \u0442\u0440\u0438 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u0430. \u041F\u0440\u0438 \u0441\u0443\u043F\u0435\u0440\u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0435 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u044F \u0447\u0438\u0441\u043B\u0430 \u0438\u043B\u0438 \u0441\u0438\u043C\u0432\u043E\u043B\u0430, \u0446\u0432\u0435\u0442 \u043D\u0435 \u0432\u0430\u0436\u0435\u043D. \u0421\u0443\u043F\u0435\u0440\u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0432\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u043E\u0433\u043E \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0430.",
              "- \u0421\u0442\u0440\u0438\u0442\u044B \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u043F\u043E\u0441\u043B\u0435 \u0441\u0432\u043E\u0435\u0439 \u043A\u0430\u0440\u0442\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0430\u044E\u0449\u0438\u0439 \u0438\u043B\u0438 \u0443\u0431\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0440\u044F\u0434 \u0442\u043E\u0433\u043E \u0436\u0435 \u0446\u0432\u0435\u0442\u0430. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0441\u043B\u0435 \u0437\u0435\u043B\u0451\u043D\u043E\u0439 \u043F\u044F\u0442\u0451\u0440\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u0431\u044B\u0441\u0442\u0440\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0443 \u0438 \u0441\u0435\u043C\u0451\u0440\u043A\u0443. \u041A\u0430\u0436\u0434\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0432\u044B\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u0438 \u0438\u0433\u0440\u0430\u0439\u0442\u0435 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter. \u041D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0440\u044F\u0434\u0430 \u043C\u0435\u043D\u044F\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F; \u0443\u0441\u043F\u0435\u0439\u0442\u0435, \u043F\u043E\u043A\u0430 \u043D\u0435 \u0441\u044B\u0433\u0440\u0430\u043B \u0434\u0440\u0443\u0433\u043E\u0439 \u0438\u0433\u0440\u043E\u043A.",
              "- \u041F\u0440\u0438 \u043E\u0431\u043C\u0435\u043D\u0435 \u0440\u0443\u043A\u0430\u043C\u0438 \u0441\u0435\u043C\u0451\u0440\u043A\u0430 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 Enter \u0438 \u043E\u0431\u043C\u0435\u043D\u044F\u0442\u044C\u0441\u044F \u0441 \u043D\u0438\u043C \u0432\u0441\u0435\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438. \u041D\u043E\u043B\u044C \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u043A\u0430\u0436\u0434\u0443\u044E \u0440\u0443\u043A\u0443 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u043F\u043E \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044E \u0438\u0433\u0440\u044B. \u0415\u0441\u043B\u0438 \u043D\u043E\u043B\u044C \u0438\u043B\u0438 \u0441\u0435\u043C\u0451\u0440\u043A\u0430 \u0431\u044B\u043B\u0438 \u0432\u0430\u0448\u0435\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u043A\u0430\u0440\u0442\u043E\u0439, \u043F\u0443\u0441\u0442\u0430\u044F \u0440\u0443\u043A\u0430 \u0434\u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u2014 \u0438\u043C\u0435\u043D\u043D\u043E \u043E\u043D \u0432\u044B\u0438\u0433\u0440\u0430\u0435\u0442 \u0440\u0430\u0443\u043D\u0434.",
              "- \u041A\u043D\u043E\u043F\u043A\u0438 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442 \u0432\u043E\u0441\u0435\u043C\u044C \u043A\u0430\u0440\u0442 \u0432 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0443\u044E \u043A\u043E\u043B\u043E\u0434\u0443 \u0438\u043B\u0438 No Mercy. \u041F\u043E\u0441\u043B\u0435 \u0442\u0430\u043A\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0432\u0441\u0435 \u043D\u0430\u0436\u0438\u043C\u0430\u044E\u0442 B; \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0431\u0435\u0440\u0451\u0442 \u0434\u0432\u0435 \u043A\u0430\u0440\u0442\u044B. \u0421\u043B\u0435\u0434\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u043A\u0430\u0440\u0442\u0443. \u0415\u0441\u043B\u0438 \u043A\u043D\u043E\u043F\u043A\u0430 \u0431\u044B\u043B\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0443 \u0438\u0433\u0440\u043E\u043A\u0430, \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u043B\u0438\u0448\u044C \u043F\u043E\u0441\u043B\u0435 \u0440\u0435\u0430\u043A\u0446\u0438\u0438 \u0432\u0441\u0435\u0445. \u0412 Flip \u043A\u043D\u043E\u043F\u043E\u043A \u043D\u0435\u0442.",
              "- \u041C\u043E\u0436\u043D\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0442\u044C \u0432\u0440\u0435\u043C\u044F \u0445\u043E\u0434\u0430. \u041D\u0435 \u0443\u0441\u043F\u0435\u0432\u0448\u0438\u0439 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043E\u0436\u0438\u0434\u0430\u044E\u0449\u0438\u0439 \u0448\u0442\u0440\u0430\u0444, \u0430 \u0435\u0441\u043B\u0438 \u0448\u0442\u0440\u0430\u0444\u0430 \u043D\u0435\u0442 \u2014 \u0431\u0435\u0440\u0451\u0442 \u043E\u0434\u043D\u0443 \u043A\u0430\u0440\u0442\u0443, \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0433\u043E \u0442\u0435\u0440\u044F\u0435\u0442 \u0445\u043E\u0434. \u0412\u044B\u0431\u043E\u0440 \u0446\u0432\u0435\u0442\u0430 \u0438 \u0440\u0435\u0430\u043A\u0446\u0438\u044F \u043D\u0430 \u043A\u043D\u043E\u043F\u043A\u0443 \u043F\u0440\u0438\u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0442 \u043E\u0442\u0441\u0447\u0451\u0442."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0438\u043B\u0438 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0446\u0432\u0435\u0442.",
              "Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0446\u0432\u0435\u0442 \u043B\u0438\u0431\u043E \u0438\u0433\u0440\u043E\u043A\u0430.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u0432\u0437\u044F\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0448\u0442\u0440\u0430\u0444\u043D\u043E\u0439 \u0434\u043E\u0431\u043E\u0440.",
              "U: \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0443\u043D\u043E \u0438\u043B\u0438 \u043F\u043E\u0439\u043C\u0430\u0442\u044C \u0437\u0430\u0431\u044B\u0432\u0448\u0435\u0433\u043E \u0435\u0433\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C.",
              "B: \u043E\u0442\u0440\u0435\u0430\u0433\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u043D\u0430 \u043A\u0430\u0440\u0442\u0443 \u043A\u043D\u043E\u043F\u043A\u0438.",
              "F: \u043E\u0441\u043F\u043E\u0440\u0438\u0442\u044C \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0434\u0438\u043A\u043E\u0439 +4.",
              "C: \u0443\u0437\u043D\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435.",
              "V: \u0443\u0437\u043D\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0446\u0432\u0435\u0442.",
              "E: \u0443\u0437\u043D\u0430\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043A\u0430\u0440\u0442 \u0443 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "G: \u0443\u0437\u043D\u0430\u0442\u044C \u043E\u0436\u0438\u0434\u0430\u044E\u0449\u0438\u0439 \u0448\u0442\u0440\u0430\u0444.",
              "Z: \u043D\u0430\u0439\u0442\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434; \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u043F\u0440\u0438 \u0441\u0442\u0440\u0438\u0442\u0430\u0445, \u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0430\u0445 \u0438 \u043A\u043D\u043E\u043F\u043A\u0430\u0445.",
              "Shift+Z: \u043D\u0430\u0439\u0442\u0438 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434; \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u043F\u0440\u0438 \u0441\u0442\u0440\u0438\u0442\u0430\u0445, \u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0430\u0445 \u0438 \u043A\u043D\u043E\u043F\u043A\u0430\u0445.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0447\u0451\u0442.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.",
              "Shift+C: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u0446\u0432\u0435\u0442\u0430\u043C; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+H: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044E; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+D: \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.",
              "Shift+M: \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.")
          ]
        end
